(4128834, 593328, 15711, '<td valign="top">Now THAT is fantastic.  WOW</td>', 'Now THAT is fantastic.  WOW', '2007-10-01 11:44:42.000000', NULL, 1),
(4128838, 593388, 15711, '<td valign="top">Oh cool.  Hmm. let''s see who took this??? I have a couple of car lovers in mind.  This is GREAT.</td>', 'Oh cool.  Hmm. let''s see who took this??? I have a couple of car lovers in mind.  This is GREAT.', '2007-10-01 11:45:27.000000', NULL, 1),
