(4134720, 592696, 18197, '<td valign="top">Very clever take on the challenge. Interesting angle. You as a photographer are apparently absent fromthe reflection. Nice take on Venice, is it? Well done!</td>', 'Very clever take on the challenge. Interesting angle. You as a photographer are apparently absent fromthe reflection. Nice take on Venice, is it? Well done!', '2007-10-02 21:05:31.000000', NULL, 1),
(4134724, 594019, 18197, '<td valign="top">Although I understand your photo and the title clarifies, it doesn''t seem to fulfill the spirit of the challenge theme.</td>', 'Although I understand your photo and the title clarifies, it doesn''t seem to fulfill the spirit of the challenge theme.', '2007-10-02 21:06:48.000000', NULL, 1),
(4134730, 593944, 18197, '<td valign="top">Focus is perfect. Meets the challenge. Composition has nice negative and positive space. A greally good take on an increasingly tiresome cliche.</td>', 'Focus is perfect. Meets the challenge. Composition has nice negative and positive space. A greally good take on an increasingly tiresome cliche.', '2007-10-02 21:08:40.000000', NULL, 1),
