(4138170, 593328, 29906, '<td valign="top">Extremely Creative. Well Done. Should get a blue ribbon in my opinion.</td>', 'Extremely Creative. Well Done. Should get a blue ribbon in my opinion.', '2007-10-03 16:55:00.000000', NULL, 1),
